import json
import re
from datetime import date

_DAY_RE = re.compile(r'\A\d{4}-\d{2}-\d{2}\Z')


def _reject_constant(name):
    raise ValueError('nonfinite JSON number: %s' % name)


def _unique_object(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise ValueError('duplicate JSON field: %r' % key)
        obj[key] = value
    return obj


def _parse_day(value, index):
    """Validate a strict YYYY-MM-DD calendar date and return it as a date."""
    if not isinstance(value, str) or not _DAY_RE.match(value):
        raise ValueError('row %d: day must be a YYYY-MM-DD string, got %r' % (index, value))
    year, month, day = (int(part) for part in value.split('-'))
    try:
        return date(year, month, day)
    except ValueError as exc:
        raise ValueError('row %d: day is not a real calendar date: %r' % (index, value)) from exc


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    if not isinstance(text, str):
        raise ValueError('input must be a JSON string, got %s' % type(text).__name__)
    try:
        rows = json.loads(text, object_pairs_hook=_unique_object,
                          parse_constant=_reject_constant)
    except json.JSONDecodeError as exc:
        raise ValueError('malformed JSON: %s' % exc) from exc
    if not isinstance(rows, list):
        raise ValueError('top-level JSON value must be an array of rows, got %s'
                         % type(rows).__name__)

    total_cents = 0
    days = []
    for index, row in enumerate(rows):
        if not isinstance(row, dict):
            raise ValueError('row %d: expected a JSON object, got %s'
                             % (index, type(row).__name__))

        tenant = row.get('tenant')
        if not isinstance(tenant, str) or not tenant:
            raise ValueError('row %d: tenant must be a nonempty string, got %r'
                             % (index, tenant))

        amount = row.get('amount_cents')
        if isinstance(amount, bool) or not isinstance(amount, int):
            raise ValueError('row %d: amount_cents must be an integer, got %r'
                             % (index, amount))

        day = _parse_day(row.get('day'), index)

        total_cents += amount
        days.append(day)

    return {
        'row_count': len(rows),
        'total_cents': total_cents,
        'first_day': min(days).isoformat() if days else None,
        'last_day': max(days).isoformat() if days else None,
    }
